  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Auth / users ──────────────────────────────────────────────\n\n/// Application profile. Credentials live in Supabase Auth; `authId` links\n/// the two. Roles: \"admin\" | \"treasurer\" | \"viewer\".\nmodel User {\n  id                  String           @id @default(cuid())\n  authId              String?          @unique\n  username            String\n  email               String           @unique\n  /// Optional contact number, stored as E.164 (+1XXXXXXXXXX, Canada/US).\n  phone               String?\n  /// Legacy column, unused since Supabase Auth handles credentials.\n  password            String?\n  role                String\n  /// Church membership: communicant (Mpandray) or not (Tsy Mpandray).\n  memberType          MemberType       @default(MPANDRAY)\n  /// Profile picture file in the private \"avatars\" bucket; null shows initials.\n  avatarPath          String?\n  /// Church responsibilities. Diakona/Birao open forum topics; Admin/Treasurer need Birao.\n  responsibilities    Responsibility[] @default([MPIARA_MIVAVAKA])\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @default(now()) @updatedAt\n  transactionsCreated Transaction[]    @relation(\"TransactionCreatedBy\")\n  transactionsUpdated Transaction[]    @relation(\"TransactionUpdatedBy\")\n  forumTopics         ForumTopic[]\n  forumComments       ForumComment[]\n  forumLikes          ForumLike[]\n  forumReads          ForumRead[]\n  forumImages         ForumImage[]\n}\n\nenum Responsibility {\n  BIRAO\n  DIAKONA\n  MPIARA_MIVAVAKA\n}\n\nenum MemberType {\n  MPANDRAY\n  TSY_MPANDRAY\n}\n\n// ─── Finance ───────────────────────────────────────────────────\n\nenum TransactionType {\n  INCOME\n  EXPENSE\n}\n\nenum PaymentMethod {\n  CASH\n  CHEQUE\n  E_TRANSFER\n  CARD\n  DIRECT_DEPOSIT\n  OTHER\n}\n\nmodel Category {\n  id           String          @id @default(cuid())\n  name         String\n  type         TransactionType\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @default(now()) @updatedAt\n  transactions Transaction[]\n\n  @@unique([name, type])\n}\n\nmodel Transaction {\n  id            String          @id @default(cuid())\n  type          TransactionType\n  /// Amount in CAD cents (always positive; `type` gives the direction).\n  amountCents   Int\n  date          DateTime        @db.Date\n  description   String\n  paymentMethod PaymentMethod\n  reference     String?\n  /// Object path inside the private `receipts` Supabase Storage bucket.\n  receiptPath   String?\n  categoryId    String?\n  category      Category?       @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  createdById   String?\n  createdBy     User?           @relation(\"TransactionCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  /// Last user who edited the transaction; null if never edited.\n  updatedById   String?\n  updatedBy     User?           @relation(\"TransactionUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @default(now()) @updatedAt\n\n  @@index([date])\n  @@index([categoryId])\n}\n\n// ─── Forum ─────────────────────────────────────────────────────\n\n/// Who can see a forum category (and every topic in it). Admins see all.\nenum ForumVisibility {\n  EVERYONE\n  DIAKONA\n  BIRAO\n}\n\nmodel ForumCategory {\n  id          String          @id @default(cuid())\n  name        String          @unique\n  description String?\n  /// Colour key from the app's palette (see src/features/forum/colors.ts).\n  color       String          @default(\"blue\")\n  visibility  ForumVisibility @default(EVERYONE)\n  /// Display order, ascending.\n  position    Int             @default(0)\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @default(now()) @updatedAt\n  topics      ForumTopic[]\n}\n\nmodel ForumTopic {\n  id             String         @id @default(cuid())\n  categoryId     String\n  category       ForumCategory  @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  title          String\n  /// Markdown.\n  body           String\n  authorId       String?\n  author         User?          @relation(fields: [authorId], references: [id], onDelete: SetNull)\n  pinned         Boolean        @default(false)\n  locked         Boolean        @default(false)\n  commentCount   Int            @default(0)\n  /// Creation time, bumped by every new comment; topics sort by it.\n  lastActivityAt DateTime       @default(now())\n  /// Set when the author/an admin edits the body or title.\n  editedAt       DateTime?\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @default(now()) @updatedAt\n  comments       ForumComment[]\n  likes          ForumLike[]\n  reads          ForumRead[]\n  images         ForumImage[]\n\n  @@index([categoryId, lastActivityAt])\n  @@index([pinned, lastActivityAt])\n}\n\nmodel ForumComment {\n  id        String         @id @default(cuid())\n  topicId   String\n  topic     ForumTopic     @relation(fields: [topicId], references: [id], onDelete: Cascade)\n  /// Markdown.\n  body      String\n  authorId  String?\n  author    User?          @relation(fields: [authorId], references: [id], onDelete: SetNull)\n  /// The comment this one answers (\"in reply to …\"), if any.\n  replyToId String?\n  replyTo   ForumComment?  @relation(\"ForumReplies\", fields: [replyToId], references: [id], onDelete: SetNull)\n  replies   ForumComment[] @relation(\"ForumReplies\")\n  editedAt  DateTime?\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @default(now()) @updatedAt\n  likes     ForumLike[]\n\n  @@index([topicId, createdAt])\n}\n\n/// A like on either a topic (its opening post) or a comment.\nmodel ForumLike {\n  id        String        @id @default(cuid())\n  userId    String\n  user      User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  topicId   String?\n  topic     ForumTopic?   @relation(fields: [topicId], references: [id], onDelete: Cascade)\n  commentId String?\n  comment   ForumComment? @relation(fields: [commentId], references: [id], onDelete: Cascade)\n  createdAt DateTime      @default(now())\n\n  @@unique([userId, topicId])\n  @@unique([userId, commentId])\n  @@index([commentId])\n}\n\n/// When a user last opened a topic; drives the unread markers.\nmodel ForumRead {\n  userId     String\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  topicId    String\n  topic      ForumTopic @relation(fields: [topicId], references: [id], onDelete: Cascade)\n  lastReadAt DateTime   @default(now())\n\n  @@id([userId, topicId])\n}\n\n/// An image uploaded for a post, stored in the private `forum` bucket. It\n/// is attached to its topic when the post is saved; access then follows the\n/// topic's category visibility (until then only the uploader can see it).\nmodel ForumImage {\n  id         String      @id @default(uuid())\n  path       String      @unique\n  uploaderId String?\n  uploader   User?       @relation(fields: [uploaderId], references: [id], onDelete: SetNull)\n  topicId    String?\n  topic      ForumTopic? @relation(fields: [topicId], references: [id], onDelete: Cascade)\n  createdAt  DateTime    @default(now())\n\n  @@index([topicId])\n}\n",
